/* Generated by tools/gen_player_path.py from Player_PathWaypointExecute. */
bool sh_path_player_step(ShPath *path, ShPathPlayer *player, int playerExtraState,
                         ShPathPoint *vec, int16_t angle, int vecCount, int32_t dt)
{
    ShPathPoint *localVec;
    int32_t playerVecDist, angleStep;
    int16_t playerRotDelta;
    angle       = path_angle(angle);
    localVec    = vec;

    path->flex_y = 0;

    switch (path->step)
    {
        case 0:
            path->waypoint = 0;
            path->step                = 1;
            break;

        case 1:
            if (localVec->vx == player->position.vx && localVec->vz == player->position.vz)
            {
                path->step = 6;
                break;
            }

            path->target_angle = path_angle(sh_fixed_atan2(localVec->vx - player->position.vx, localVec->vz - player->position.vz));
            path_shortest(player->rotation.vy, path->target_angle, &playerRotDelta);

            if (abs(playerRotDelta) < (4096 >> 6))
            {
                player->rotation.vy = path->target_angle;
                path->step                  = 3;
                break;
            }

            if (playerRotDelta < 0)
            {
                player->cutscene_state = 4;
                sh_path_state_set(player, 57);
                path->step = 2;
            }
            else
            {
                player->cutscene_state = 3;
                sh_path_state_set(player, 56);
                path->step = 2;
            }

            break;

        case 2:
            path_shortest(player->rotation.vy, path->target_angle, &playerRotDelta);
            if (abs(playerRotDelta) < (4096 >> 6))
            {
                player->rotation.vy = path->target_angle;
                path->step                  = 3;
            }
            break;

        case 3:
            playerVecDist = sh_fixed_sqrt0(PATH_DISTANCE_SQR(localVec[0], player->position));
            if (abs((int)playerVecDist) < 38) 
            {
                sh_path_state_set(player, 52);
                path->step = 8;
                break;
            }

            sh_path_state_set(player, playerExtraState);
            switch (playerExtraState)
            {
                case 54:
                    player->cutscene_state = 0;
                    break;

                case 53:
                    player->cutscene_state = 1;
                    break;
            }

            path->step = 4;
            break;

        case 4:
            path->target_angle = path_angle(sh_fixed_atan2(localVec[path->waypoint].vx -
                                                            player->position.vx, localVec[path->waypoint].vz -
                                                            player->position.vz));
            if (path->waypoint + 1 < vecCount)
            {
                path->next_angle = path_angle(sh_fixed_atan2(localVec[path->waypoint + 1].vx -
                                                                player->position.vx, localVec[path->waypoint + 1].vz -
                                                                player->position.vz));
            }
            else
            {
                path->next_angle = path->target_angle;
            }

            path->previous_distance = sh_fixed_sqrt0(PATH_DISTANCE_SQR(localVec[path->waypoint], player->position));
            path->step                = 5;

            path_shortest(player->rotation.vy, path->next_angle, &path->flex_y);

            path->flex_y = sh_q12_clamp(path->flex_y, -512, 512);

            break;

        case 5:
            if (path->waypoint + 1 < vecCount)
            {
                path->next_angle = sh_fixed_atan2(localVec[path->waypoint + 1].vx -
                                                   player->position.vx, localVec[path->waypoint + 1].vz -
                                                   player->position.vz);
            }
            else
            {
                path->next_angle = sh_fixed_atan2(localVec[path->waypoint].vx -
                                                   player->position.vx, localVec[path->waypoint].vz -
                                                   player->position.vz);
            }

            path->next_angle = path_angle(path->next_angle);

            path_shortest(player->rotation.vy, path->next_angle, &playerRotDelta);

            
            angleStep = PATH_TIMESTEP(dt, (playerRotDelta < 512) ? 32 : 256);

            if (abs(playerRotDelta) < (4096 >> 6))
            {
                player->rotation.vy = path->next_angle;
            }
            else if (playerRotDelta < 0)
            {
                player->rotation.vy -= angleStep;
            }
            else
            {
                player->rotation.vy += angleStep;
            }

            player->rotation.vy = path_angle(player->rotation.vy);

            playerVecDist = sh_fixed_sqrt0(PATH_DISTANCE_SQR(localVec[path->waypoint], player->position));

            
            if (playerVecDist < PATH_TO_Q8((playerExtraState - 53) * 614 + 614) ||
                (path->previous_distance < playerVecDist && path->waypoint != vecCount - 1))
            {
                path->waypoint++;

                playerVecDist = path->waypoint < vecCount ? sh_fixed_sqrt0(PATH_DISTANCE_SQR(localVec[path->waypoint], player->position)) : 0;

                if (path->waypoint == vecCount)
                {
                    path->step = 6;
                }
                else
                {
                    path->step = 4;
                }
            }

            path->previous_distance = playerVecDist;

            path_shortest(player->rotation.vy, path->next_angle, &path->flex_y);
            path->flex_y = sh_q12_clamp(path->flex_y, -512, 512);
            break;

        case 6:
            path_shortest(player->rotation.vy, angle, &playerRotDelta);
            if (abs(playerRotDelta) < (4096 >> 6))
            {
                player->rotation.vy = angle;
                path->step                  = 8;
                break;
            }

            if (playerRotDelta < 0)
            {
                player->cutscene_state = 4;
                sh_path_state_set(player, 57);
            }
            else
            {
                player->cutscene_state = 3;
                sh_path_state_set(player, 56);
            }

            path->step = 7;
            break;

        case 7:
            path_shortest(player->rotation.vy, angle, &playerRotDelta);
            if (abs(playerRotDelta) < (4096 >> 6))
            {
                player->rotation.vy = angle;
                sh_path_state_set(player, 52);
                player->cutscene_state = 0;
                path->step = 8;
            }
            break;

        case 8:
            player->animation_reset                                                              = true;
            path->target_angle                                               = 0;
            path->step                                                              = 0;
            player->move_speed = 0;
            return true;
    }

    return false;
}
